<script setup lang="ts">import{computed}from'vue';import{truncateDiff}from'../composables/diff';import CopyButton from'./CopyButton.vue';const p=defineProps<{diff:string;path?:string}>();defineEmits<{open:[]}>();const preview=computed(()=>truncateDiff(p.diff));</script>
<template><section class="diff-card copy-surface"><header><div><span class="file-icon">±</span><strong>{{path||'文件变更'}}</strong></div><div class="diff-actions"><CopyButton :text="diff" label="复制差异"/><button class="text-button" @click="$emit('open')">查看完整差异</button></div></header><pre><code><template v-for="(line,i) in preview.text.split('\n')" :key="i"><span :class="line.startsWith('+')?'add':line.startsWith('-')?'remove':'context'">{{line}}
</span></template></code></pre><footer v-if="preview.truncated">共 {{preview.lineCount}} 行 · 已显示前 {{preview.text.split('\n').length}} 行</footer></section></template>
